const noop={type:'noop'}, unsupported={type:'unsupported'};
const codes={Grass:'G',Fire:'R',Water:'W',Lightning:'L',Psychic:'P',Fighting:'F',Darkness:'D',Metal:'M',Colorless:'C',Dragon:'N',Fairy:'Y'};
const flip=heads=>({type:'coinFlip',heads,tails:noop});
const status=s=>({type:'status',target:'opponentActive',status:s});
